const fs=require('node:fs');
const path=require('node:path');
const sharp=require(process.env.YAMB_SHARP_PATH||'sharp');
const {resolve:resolveQuality}=require('../www/theme-quality-assets.js');
const root=path.resolve(__dirname,'..');
const raw=path.join(root,'tmp/emulator-league-2026-10-28');
const out=path.join(root,'docs/theme-visual-audit/emulator-league-2026-10-28');
const manifest=JSON.parse(fs.readFileSync(path.join(root,'source-assets/theme-quarterly-league-v2/manifest.json'),'utf8'));
const names=['Zelena','Svetlo zlato','Trula višnja','Plavi okean','Neon Cyber','Kraljevski ametist','Vaskršnja','Pustinjsko staklo','Mesečev sjaj','Severna maglina'];
const entries=[];
const results=manifest.themes.map((group,index)=>{
  const theme=group.id;
  const menu=theme==='dark'?'dark-main-small-settled':`${theme}-main`;
  const league=theme==='dark'?'dark-league-observed':['light','moon','severna'].includes(theme)?`${theme}-league-ready`:`${theme}-league`;
  const files=[menu,league,`${theme}-hof-medals`,`${theme}-hof-champions`];
  files.forEach((file,i)=>entries.push({file,theme,title:`${names[index]} — ${['meni','Liga / Majstor','Dvorana slavnih / Medalje','Dvorana slavnih / Šampioni'][i]}`}));
  const assets=group.assets.map(asset=>({role:asset.role,master:asset.master,production:asset.production.map(p=>({canonical:p.file,resolved:'www/'+resolveQuality(p.file.replace(/^www\//,''))}))}));
  return {theme,name:names[index],status:theme==='dark'?'Referenca pregledana; zajednički lokalni ugovor proveriti posle deploya':'Potrebna dorada — lokalno usklađeno, Android potvrda čeka deploy',pngIdentityStatus:'U snimljenim prikazima odgovarajući tematski PNG; nema potrebe za novim crtežima u ovom prolazu.',layoutFinding:'R18: objavljena verzija nema jednake mere i tipografiju rezimea/navigacije kao Zelena.',tabFinding:['easter','desert','severna'].includes(theme)?'R19: stara stanja tabova nadjačavaju materijal/paletu; lokalno nadjačana za sve teme.':'Lokalni ugovor proverava aktivno, neaktivno i hover stanje.',firstSelection:theme==='dark'?'Početna tema; završno vraćanje uspelo.':'Prvi izbor vratio prethodnu temu; ponovljeni izbor uspeo. Nije dokaz stabilnog hladnog prelaska.',evidence:files.map(x=>x+'.jpg'),masterCount:13,productionPngCount:14,sharedClose:'Zaseban kanonski room-controls/close-v1.png iste teme; nije uključen u 14 fajlova ligaškog paketa.',assets};
});
entries.push({file:'dark-league-amater-ready',theme:'extra',title:'Zelena — navigacija na Amater'},
  {file:'dark-league-alltime',theme:'extra',title:'Zelena — navigacija na Sva vremena'},
  {file:'dark-main-restored-original',theme:'extra',title:'Završno vraćanje Zelene / originalna rezolucija'},
  {file:'android-home-observed',theme:'extra',title:'Raniji prekid — Android poruka aplikacija ne odgovara'});
const report={date:'2026-10-28',room:'Kvartalna liga',scope:'Stvarni Android emulator 360×780: meni, Liga/Majstor, Medalje i Šampioni u svih deset tema. Green Amater/Sva vremena dodatno. Green snimci pre prekida sačuvani; preostalih devet snimljeno posle ponovnog otvaranja.',deployment:'Android galerija prikazuje postojeću objavljenu aplikaciju, pre novih lokalnih CSS izmena. Bez commita/deploya.',recovery:'Na početku nastavka emulator na Android Home, ADB i snimci odgovaraju. Aplikacija ručno otvorena preko postojeće ikone; prijava očuvana i UI odgovara. Raniji ANR je stvaran zaseban nalaz nepoznatog uzroka; tokom nastavka nije ponovljen.',localChanges:{R18:'Jedna Green geometrija i tipografija za svih deset tema: okvir, rezime u dve kolone, zadržana PNG skala, naslov, rang, 44px navigacija sa 10px vidljivom tačkom; uklonjeno nasleđeno tablet translate pomeranje. Duga imena ne skupljaju avatar.',R19:'Tabovi uključujući hover/active koriste aktuelne tematske površine, ink i akcent; nadjačana stara Easter/Desert/Severna stanja.',css:'www/theme-quarterly-league-room.css',cacheVersion:9},tests:{command:'npm run check:theme-quarterly-league-final',result:'PASS i posle lokalne CSS dorade: PNG manifest/hashovi, kanonske putanje, kvartali, intro konfiguracija, mere i kontrast paleta.',runtime:'scripts/test-quarterly-league-layout-runtime.cjs',runtimeResult:'PASS: 40 lokalnih Chromium kombinacija (10 tema × 320×568, 360×780, 411×891, 768×1024), stvarni renderer sa sintetičkim podacima i bez mreže/naloga. Izračunate mere/fontovi prate Green; tabovi prate paletu; duga imena ne prelaze karticu.',runtimeEvidence:'tmp/quarterly-layout-runtime/report.json',fontLimit:'Montserrat je deklarisan; izolovani offline fixture može koristiti Arial fallback. Pravi Android snimci su zaseban dokaz.'},safety:'Nema nove partije, prihvaćenog duela, nagrade, kupovine ili slanja poruka. Novi blokirajući poziv Lidije Trajković odbijen uz izričito korisnikovo odobrenje. Automatski test interstitiali zatvoreni Android Back kontrolom bez klika na oglas.',restoration:'Zelena vraćena kroz UI; resetovani wm size/density na originalnih 1440×3120 /560dpi. Emulator otvoren i prijavljen.',limits:['Ovo nije pregled svake stranice svih šest rangova u svih deset tema: detaljno je prikazan Majstor, uz Green Amater/Sva vremena. PNG inventar šest rangova je statički proveravan.','Nema novog Android prikaza šampionskog obaveštenja, nagradne potvrde, prazne/error liste, svih kvartala ili drugog jezika. Nisu menjani datum, profil ili server radi izazivanja tih stanja.','Screenshoti ne mere tačno trajanje intra, fluidnost ili hladni mrežni transfer. Objavljena verzija je u svih devet novih izbora prvo vratila prethodnu temu.','Nove lokalne ispravke zahtevaju korisnikov deploy i novu Android potvrdu. Nije fizički Samsung S25 test.'],results,entries};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function main(){
  fs.mkdirSync(out,{recursive:true});
  const runtimePath=path.join(root,'tmp/quarterly-layout-runtime/report.json');
  const runtime=JSON.parse(fs.readFileSync(runtimePath,'utf8'));
  if(runtime.rows.length!==40)throw Error('Forty successful local layout cases required.');
  fs.copyFileSync(runtimePath,path.join(out,'local-layout-report.json'));
  report.tests.runtimeEvidence='local-layout-report.json';
  report.results[0].layoutFinding='Zelena je referenca rasporeda; lokalni zajednički ugovor čuva njene mere i dodaje zaštitu dugih imena/tablet granica.';
  for(const entry of entries)await sharp(path.join(raw,entry.file+'.png')).resize({width:540}).jpeg({quality:88,chromaSubsampling:'4:4:4'}).toFile(path.join(out,entry.file+'.jpg'));
  fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2)+'\n');
  const card=e=>`<article><h3>${esc(e.title)}</h3><a href="${e.file}.jpg"><img loading="lazy" src="${e.file}.jpg" alt="${esc(e.title)}"></a></article>`;
  fs.writeFileSync(path.join(out,'index.html'),`<!doctype html><html lang="sr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kvartalna liga — emulator 28.10.</title><style>*{box-sizing:border-box}body{font:16px/1.5 system-ui;background:#14232e;color:#edf5fc;margin:0;padding:24px}main{max-width:1500px;margin:auto}a{color:#afe4ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}article{background:#233847;border:1px solid #7997a9;border-radius:12px;padding:12px}img{width:100%;height:auto}h3{font-size:17px}nav{display:flex;gap:12px;flex-wrap:wrap}</style><main><h1>Kvartalna liga — svih deset tema</h1><p>${esc(report.scope)}</p><p><b>${esc(report.deployment)}</b></p><p>${esc(report.recovery)}</p><nav><a href="report.json">PNG putanje i puna evidencija</a>${results.map(r=>`<a href="#${r.theme}">${esc(r.name)}</a>`).join('')}</nav><h2>Lokalne dorade koje galerija još ne potvrđuje</h2><p>${esc(report.localChanges.R18)}</p><p>${esc(report.localChanges.R19)}</p><p>${esc(report.tests.runtimeResult)} ${esc(report.tests.fontLimit)}</p><h2>Granice provere</h2><ul>${report.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${results.map(r=>`<section id="${r.theme}"><h2>${esc(r.name)}</h2><p>${esc(r.status)}. ${esc(r.tabFinding)}</p><div class="grid">${entries.filter(e=>e.theme===r.theme).map(card).join('')}</div></section>`).join('')}<h2>Dodatni dokazi</h2><div class="grid">${entries.filter(e=>e.theme==='extra').map(card).join('')}</div><p>${esc(report.safety)}</p><p>${esc(report.restoration)}</p></main></html>`);
  console.log(`League: ${results.length} themes, ${entries.length} scoped Android screenshots.`);
}
main().catch(e=>{console.error(e);process.exitCode=1;});
